[{"order":1,"type":"heading","text":"State Management Patterns in NativeScript"},{"order":2,"type":"paragraph","text":"Managing state effectively in cross-platform mobile applications is crucial for performance and maintainability. In NativeScript, state management can range from simple observable properties to robust unidirectional data flows resembling Redux or Vuex."},{"order":3,"type":"subheading","text":"1. NativeScript Observable (Built-in State Management)"},{"order":4,"type":"paragraph","text":"NativeScript provides a built-in Observable class out of the box. This is ideal for smaller applications or individual page components. It notifies the UI whenever properties change."},{"order":5,"type":"code","text":"import { Observable } from '@nativescript/core';

export class CounterViewModel extends Observable {
    constructor() {
        super();
        this.set('counter', 0);
    }

    increment() {
        let current = this.get('counter');
        this.set('counter', current + 1);
    }
}"},{"order":6,"type":"subheading","text":"2. Reactive State with RxJS"},{"order":7,"type":"paragraph","text":"For apps that require complex asynchronous event streams, RxJS is a powerful companion. You can leverage BehaviorSubjects to maintain a single source of truth that multiple components can subscribe to."},{"order":8,"type":"code","text":"import { BehaviorSubject } from 'rxjs';

interface AppState {
    user: string | null;
    isLoggedIn: boolean;
}

class Store {
    private state = new BehaviorSubject<AppState>({
        user: null,
        isLoggedIn: false
    });

    public state$ = this.state.asObservable();

    public login(username: string) {
        this.state.next({ user: username, isLoggedIn: true });
    }

    public logout() {
        this.state.next({ user: null, isLoggedIn: false });
    }
}

export const globalStore = new Store();"},{"order":9,"type":"subheading","text":"3. Framework-Specific Patterns"},{"order":10,"type":"bullet_point","text":"Angular: Utilize services with RxJS BehaviorSubjects or NgRx for enterprise-grade global state management."},{"order":11,"type":"bullet_point","text":"Vue: Use Pinia or Vuex to manage centralized stores cleanly across NativeScript-Vue components."},{"order":12,"type":"bullet_point","text":"React: NativeScript-React supports standard hooks like useReducer and useContext, or external libraries like Zustand."},{"order":13,"type":"subheading","text":"Best Practices"},{"order":14,"type":"bullet_point","text":"Keep local UI state (like text input focus) inside the component."},{"order":15,"type":"bullet_point","text":"Elevate shared data (like user profiles, authentication tokens, and app preferences) to a global store."},{"order":16,"type":"bullet_point","text":"Avoid mutating state directly; always use actions or dispatch methods to ensure predictable updates."}]
